SELECT b.*, c.name as categoryName
FROM bill b
LEFT JOIN category c ON b.category_id = c.id
WHERE b.user_id = #{userId}

    AND (b.visible = 'PRIVATE' OR b.family_id = #{familyId})


    AND b.date >= #{startDate}


    AND b.date <= #{endDate}


    AND b.type = #{type}


    AND b.category_id = #{categoryId}


    AND b.visible = #{visible}


    AND b.amount >= #{minAmount}


    AND b.amount <= #{maxAmount}



        ORDER BY b.amount ASC, b.id DESC


        ORDER BY b.amount DESC, b.id DESC


        ORDER BY b.date ASC, b.id DESC


        ORDER BY b.date DESC, b.id DESC


        ORDER BY b.date DESC, b.id DESC

SELECT b.*, c.name as categoryName, u.nickname
FROM bill b
LEFT JOIN category c ON b.category_id = c.id
LEFT JOIN user u ON b.user_id = u.id
WHERE b.family_id = #{familyId}
    AND b.visible = 'FAMILY'

    AND b.user_id = #{userId}


    AND b.date >= #{startDate}


    AND b.date <= #{endDate}


    AND b.type = #{type}


    AND b.category_id = #{categoryId}

ORDER BY b.date DESC, b.id DESC

